package com.bank.lateraljoin.repository;
import com.bank.lateraljoin.model.Txn;
import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.*;
import java.util.stream.*;

public class TxnRepository {
    private final List<Txn> all = new ArrayList<>();
    public TxnRepository() {
        LocalDateTime base = LocalDateTime.of(2026,10,25,10,0);
        for (int i = 0; i < 5; i++) all.add(new Txn("SAV2001", new BigDecimal(1000 + i*10), base.plusMinutes(i)));
        for (int i = 0; i < 2; i++) all.add(new Txn("CUR3001", new BigDecimal(500 + i*10),  base.plusMinutes(i)));
    }
    // Mimics the LATERAL inner query: latest N txns for ONE account id
    public List<Txn> latestFor(String accountId, int n) {
        return all.stream().filter(t -> t.getAccountId().equals(accountId))
            .sorted(Comparator.comparing(Txn::getTs).reversed())
            .limit(n).collect(Collectors.toList());
    }
}
