package com.bank.lateraljoin.service;
import com.bank.lateraljoin.model.Txn;
import com.bank.lateraljoin.repository.TxnRepository;
import java.util.*;
import java.util.logging.*;

public class AccountService {
    private static final Logger log = Logger.getLogger(AccountService.class.getName());
    static {
        Handler h = new ConsoleHandler(); h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false); log.addHandler(h);
    }
    private final TxnRepository repo;
    public AccountService(TxnRepository repo) { this.repo = repo; }

    // CROSS JOIN LATERAL: for each account, run the per-row top-N lookup
    public Map<String, List<Txn>> recentPerAccount(List<String> accountIds, int n) {
        Map<String, List<Txn>> out = new LinkedHashMap<>();
        for (String id : accountIds) {
            List<Txn> latest = repo.latestFor(id, n);   // this is the LATERAL inner query
            out.put(id, latest);
            log.info(() -> "LATERAL " + id + " -> " + latest.size() + " latest txns");
        }
        return out;
    }
}
