package com.bank.lateraljoin;
import com.bank.lateraljoin.repository.TxnRepository;
import com.bank.lateraljoin.service.AccountService;
import java.util.List;
import java.util.logging.*;

public class LateralDemo {
    public static void main(String[] args) {
        AccountService svc = new AccountService(new TxnRepository());
        svc.recentPerAccount(List.of("SAV2001","CUR3001"), 3)
           .forEach((id, txns) -> txns.forEach(t ->
               System.out.println(id + " | " + t.getAmount() + " | " + t.getTs())));
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n", r.getMillis(), r.getLevel(), formatMessage(r));
    }
}
